'use client';

import { useCallback, useId, useRef, type ComponentPropsWithRef, type KeyboardEvent } from 'react';
import '../theme.css';
import './search-field.css';

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

export interface SearchFieldProps
  extends Omit<ComponentPropsWithRef<'input'>, 'value' | 'defaultValue' | 'onChange' | 'type' | 'size'> {
  /** Always required. Hidden from view unless showLabel is set. */
  label: string;
  showLabel?: boolean;
  value: string;
  onValueChange: (value: string) => void;
  /** Accessible name of the clear button. */
  clearLabel?: string;
}

/**
 * Search input with a clear button. Escape clears a non-empty value.
 * `ref` reaches the input, so a parent can move focus back to the field.
 */
export function SearchField({
  label,
  showLabel = false,
  value,
  onValueChange,
  clearLabel = 'Clear search',
  id,
  className,
  disabled,
  readOnly,
  onKeyDown,
  ref,
  ...rest
}: SearchFieldProps) {
  const fallbackId = useId();
  const inputId = id ?? fallbackId;
  const inputRef = useRef<HTMLInputElement | null>(null);
  // One stable callback that also feeds the caller's ref. It returns a
  // cleanup (React 19), so the caller's own cleanup runs on detach and a
  // callback ref that returns a cleanup never receives null.
  const setInput = useCallback(
    (node: HTMLInputElement | null) => {
      inputRef.current = node;
      const callerCleanup = typeof ref === 'function' ? ref(node) : undefined;
      if (ref && typeof ref !== 'function') ref.current = node;
      return () => {
        inputRef.current = null;
        if (typeof callerCleanup === 'function') callerCleanup();
        else if (typeof ref === 'function') ref(null);
        else if (ref) ref.current = null;
      };
    },
    [ref],
  );
  const clearable = value !== '' && !disabled && !readOnly;

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    onKeyDown?.(event);
    // Escape during IME composition cancels the composition, not the query.
    if (event.defaultPrevented || event.key !== 'Escape' || event.nativeEvent.isComposing || !clearable) return;
    event.preventDefault();
    event.stopPropagation();
    onValueChange('');
  }

  return (
    <div className={cx('ws-search', className)}>
      <label className="ws-search__label" htmlFor={inputId} data-hidden={showLabel ? undefined : ''}>
        {label}
      </label>
      <div className="ws-search__control">
        <svg className="ws-search__icon" viewBox="0 0 16 16" fill="none" aria-hidden="true">
          <circle cx="7" cy="7" r="4.25" stroke="currentColor" strokeWidth="1.5" />
          <path d="M10.25 10.25L13.5 13.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
        <input
          {...rest}
          ref={setInput}
          id={inputId}
          className="ws-search__input"
          type="search"
          value={value}
          disabled={disabled}
          readOnly={readOnly}
          onChange={(event) => onValueChange(event.target.value)}
          onKeyDown={handleKeyDown}
        />
        {clearable ? (
          <button
            type="button"
            className="ws-search__clear"
            aria-label={clearLabel}
            onClick={() => {
              onValueChange('');
              inputRef.current?.focus();
            }}
          >
            <svg viewBox="0 0 16 16" fill="none" aria-hidden="true">
              <path d="M4.5 4.5l7 7M11.5 4.5l-7 7" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
            </svg>
          </button>
        ) : null}
      </div>
    </div>
  );
}

.ws-search {
  box-sizing: border-box;
  display: grid;
  gap: 6px;
  min-width: 0;
  font-family: var(--ws-font-sans);
}

.ws-search__label {
  color: var(--ws-color-text);
  font-size: var(--ws-text-sm);
  font-weight: var(--ws-weight-medium);
  line-height: var(--ws-leading-tight);
}

.ws-search__label[data-hidden] {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.ws-search__control {
  position: relative;
  display: flex;
  align-items: center;
}

.ws-search__icon {
  position: absolute;
  left: 10px;
  width: var(--ws-icon-size);
  height: var(--ws-icon-size);
  color: var(--ws-color-text-muted);
  pointer-events: none;
}

.ws-search__input {
  box-sizing: border-box;
  width: 100%;
  min-height: var(--ws-control-height);
  margin: 0;
  padding: 0 36px 0 34px;
  border: 1px solid var(--ws-color-field-line);
  border-radius: var(--ws-radius-sm);
  background: var(--ws-color-panel);
  color: var(--ws-color-text);
  font-family: var(--ws-font-sans);
  font-size: var(--ws-text-md);
  font-weight: var(--ws-weight-regular);
  line-height: normal;
  letter-spacing: 0;
  text-align: start;
  appearance: none;
  transition: border-color var(--ws-duration-fast) var(--ws-ease);
}

.ws-search__input::placeholder {
  color: var(--ws-color-text-muted);
  opacity: 1;
}

.ws-search__input::-webkit-search-cancel-button,
.ws-search__input::-webkit-search-decoration {
  appearance: none;
}

.ws-search__input:hover {
  border-color: var(--ws-color-text-muted);
}

.ws-search__input:focus {
  border-color: var(--ws-color-accent);
  outline: var(--ws-focus-width) solid var(--ws-color-focus);
  outline-offset: 1px;
}

.ws-search__input:disabled {
  border-color: var(--ws-color-line);
  background: var(--ws-color-inset);
  color: var(--ws-color-text-muted);
  cursor: not-allowed;
}

.ws-search__clear {
  position: absolute;
  right: 6px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--ws-radius-xs);
  background: transparent;
  color: var(--ws-color-text-muted);
  cursor: pointer;
  transition: background-color var(--ws-duration-fast) var(--ws-ease);
}

.ws-search__clear svg {
  width: 14px;
  height: 14px;
}

.ws-search__clear:hover {
  background: var(--ws-color-surface);
  color: var(--ws-color-text);
}

.ws-search__clear:focus-visible {
  outline: var(--ws-focus-width) solid var(--ws-color-focus);
  outline-offset: 0;
}

/* Touch: a 16px field stops iOS from zooming on focus; the clear target grows. */
@media (pointer: coarse) {
  .ws-search__input {
    font-size: 16px;
  }

  .ws-search__clear {
    right: 4px;
    width: 36px;
    height: 36px;
  }
}
